def _unpack_and_run() -> None:
    raw_zip = base64.b85decode(_PAYLOAD.encode("ascii"))
    runtime_root = Path(tempfile.mkdtemp(prefix="telegram-gmp-bot-"))
    archive = runtime_root / "bundle.zip"
    archive.write_bytes(raw_zip)

    with zipfile.ZipFile(archive, "r") as zf:
        zf.extractall(runtime_root / "project")

    candidates = list((runtime_root / "project").rglob("app.py"))
    if not candidates:
        raise RuntimeError("Embedded bot application was not found.")

    original_app = candidates[0]
    project_root = original_app.parent

    # Make all original absolute imports (config, models, bot.*, web.*)
    # resolve exactly as they did in the original project.
    sys.path.insert(0, str(project_root))
    os.chdir(project_root)

    # Run the original application as __main__, preserving its full startup,
    # FastAPI admin panel, Telegram polling and database initialization.
    runpy.run_path(str(original_app), run_name="__main__")

if __name__ == "__main__":
    _unpack_and_run()
